{
  "root": "main_stack",
  "state": {
    "trafficData": [
      { "Date": "2023-10-01", "Visitors": 1200, "Page Views": 3500 },
      { "Date": "2023-10-02", "Visitors": 1350, "Page Views": 4100 },
      { "Date": "2023-10-03", "Visitors": 1100, "Page Views": 3200 },
      { "Date": "2023-10-04", "Visitors": 1450, "Page Views": 4600 },
      { "Date": "2023-10-05", "Visitors": 1600, "Page Views": 5100 },
      { "Date": "2023-10-06", "Visitors": 1000, "Page Views": 2900 },
      { "Date": "2023-10-07", "Visitors": 950, "Page Views": 2800 }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_icon_stack",
        "summary_text",
        "divider_1",
        "daily_metrics_heading",
        "traffic_table",
        "divider_2",
        "performance_heading",
        "highest_visitor_day",
        "average_page_views",
        "divider_3",
        "actions_heading",
        "actions_stack"
      ]
    },
    "title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_graph_up",
        "title_text"
      ]
    },
    "icon_graph_up": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000576_01_2_graph-up.svg"
      },
      "children": []
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "October 2023 Website Traffic Summary",
        "variant": "h2"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "Here's a summary of your website traffic for the first week of October 2023, highlighting daily visitors and page views."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "daily_metrics_heading": {
      "type": "Text",
      "props": {
        "text": "Daily Traffic Metrics",
        "variant": "h3"
      },
      "children": []
    },
    "traffic_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "Date", "label": "Date" },
          { "key": "Visitors", "label": "Visitors" },
          { "key": "Page Views", "label": "Page Views" }
        ],
        "statePath": "/trafficData",
        "domain": "status",
        "preferredPresentation": "table",
        "numericColumns": ["Visitors", "Page Views"]
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "performance_heading": {
      "type": "Text",
      "props": {
        "text": "Performance Highlights",
        "variant": "h3"
      },
      "children": []
    },
    "highest_visitor_day": {
      "type": "Text",
      "props": {
        "text": "Highest Visitor Day: October 5, 2023, with 1600 visitors."
      },
      "children": []
    },
    "average_page_views": {
      "type": "Text",
      "props": {
        "text": "Average Daily Page Views: Approximately 3743 page views per day."
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "monthly_report_button",
        "previous_week_button"
      ]
    },
    "monthly_report_button": {
      "type": "Button",
      "props": {
        "label": "View Monthly Report"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/reports/monthly"
          }
        }
      },
      "children": []
    },
    "previous_week_button": {
      "type": "Button",
      "props": {
        "label": "Previous Week Data"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/data/previous_week"
          }
        }
      },
      "children": []
    }
  }
}
